//#region src/psql/wire/notify.ts
var NoticeMultiplexer = class {
	constructor() {
		this.noticeHandlers = /* @__PURE__ */ new Set();
		this.notificationHandlers = /* @__PURE__ */ new Set();
		this.lastHandlerError = void 0;
	}
	/** Subscribe to NoticeResponse. Returns a disposer. */
	onNotice(handler) {
		this.noticeHandlers.add(handler);
		return () => this.noticeHandlers.delete(handler);
	}
	/** Subscribe to NotificationResponse (LISTEN/NOTIFY). Returns a disposer. */
	onNotification(handler) {
		this.notificationHandlers.add(handler);
		return () => this.notificationHandlers.delete(handler);
	}
	emit(notice) {
		for (const h of this.noticeHandlers) try {
			h(notice);
		} catch (err) {
			this.lastHandlerError = err;
		}
	}
	emitNotification(channel, payload, pid) {
		for (const h of this.notificationHandlers) try {
			h(channel, payload, pid);
		} catch (err) {
			this.lastHandlerError = err;
		}
	}
	/** Drop every subscriber. Called by Connection.close(). */
	clear() {
		this.noticeHandlers.clear();
		this.notificationHandlers.clear();
	}
};
//#endregion
export { NoticeMultiplexer };
